parameters.jsCode:
const body = $json.body || {};
const message = body.message || body.text || body.input || '';

return [{
  json: {
    request_id: body.request_id || `CHK1-${Date.now()}`,
    session_id: body.session_id || body.email || body.phone || 'session-demo',
    channel: body.channel || 'webhook-postman',
    user_message: String(message).trim(),
    event_context: {
      event_name: body.event?.event_name || body.event_name || null,
      event_date: body.event?.event_date || body.event_date || null,
      order_id_masked: body.order?.order_id ? `ORD-***${String(body.order.order_id).slice(-3)}` : null
    },
    deterministic_control: {
      stage: 'normalizacion_entrada',
      empty_message: !String(message).trim(),
      pii_policy: 'no_solicitar_datos_sensibles'
    }
  }
}];

parameters.text:
={{ `Mensaje del usuario:
${$json.user_message}

Contexto disponible:
${JSON.stringify($json.event_context)}

Canal: ${$json.channel}
Request ID: ${$json.request_id}` }}

parameters.jsCode:
const item = $input.first().json;
const output = item.output || item.text || item.response || 'Sin respuesta generada por el agente.';
const intermediateSteps = item.intermediateSteps || item.intermediate_steps || [];

return [{
  json: {
    status: item.error ? 'agent_error' : 'processed',
    agent_output: output,
    observability_log: {
      workflow: 'checkpoint1_ticketing_cultural',
      version: '1.0.0',
      execution_id: $execution.id,
      timestamp: new Date().toISOString(),
      agent_mode: 'tools_agent',
      max_iterations: 7,
      tool_connected: 'Google Docs Tool — políticas de ticketing',
      intermediate_steps_count: Array.isArray(intermediateSteps) ? intermediateSteps.length : null,
      human_supervision_required: /devoluci[oó]n|cancelaci[oó]n|cambio|revisi[oó]n humana|no tengo informaci[oó]n/i.test(String(output)),
      error: item.error || null
    }
  }
}];

parameters.message:
={{ `Resultado del agente:
${$json.agent_output}

Log de observabilidad:
${JSON.stringify($json.observability_log, null, 2)}` }}
